// editorial/emails/newsletter.tsx, from hyperelements.dev/templates. Replace the brand block with your own brand.

import { lint } from "@hyper-elements/lint";
import { Button, Column, Email, Heading, Image, Link, Section, Text, defineTheme, prop, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";
import { field, template } from "@hyper-elements/react/template";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show. */
  address?: string;
  /** The brand's site, and the hosts its links may go to (`acme.example`, or `*.acme.example`). */
  links: { site: string; domains: readonly string[]; params?: Readonly<Record<string, string>> };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Orbit",
  theme: defineTheme({
    colors: {
      background: "#ffffff",
      foreground: "#0b1020",
      primary: "#4f46e5",
      primaryForeground: "#ffffff",
      border: "#e2e5ee",
      muted: "#5b6478",
      surface: "#f4f5fa",
      accent: "#2dd4bf",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "Inter, 'Helvetica Neue', Arial, sans-serif" },
    fontSizes: { body: 16, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 16, lg: 24, xl: 40 },
    radii: { sm: 6, md: 12 },
    elements: {
      Heading: {
        fontWeight: 700,
        by: {
          level: {
            1: { fontSize: 32, lineHeight: 1.15 },
            2: { fontSize: 24, lineHeight: 1.25 },
            3: { fontSize: 19, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/kits/assets/brands/orbit/logo.png", width: 480, height: 120, alt: "Orbit" },
  address: "1 Main Street, Springfield",
  links: { site: "https://orbit.example", domains: ["orbit.example", "*.orbit.example"] },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
  ],
};
// brand: end

// From _categories/newsletter.ts
const newsletter = {
  group: "Content",
  label: "Newsletter",
  roots: ["Email", "Page"],
  useWhen: "A regular issue of written news: a subject, a lead, and sections the writer fills in",
  avoidWhen: "One announcement (use announcement), or a summary built from data (use digest)",
  required: {
    subject: prop.text({ label: "Subject", required: true, maxLength: 70 }),
    preview: prop.text({ label: "Preview text", required: true, maxLength: 120 }),
  },
  example: {
    subject: "What's new this month",
    preview: "Faster exports, notes in your own voice, and a date for the open house",
  },
} as const;

// The template
function editorialNewsletter(brand: Brand) {
  const href = (to: string) => {
    const url = new URL(to, brand.links.site);
    for (const [key, value] of Object.entries(brand.links.params ?? {})) url.searchParams.set(key, value);
    return url.toString();
  };
  return template({
    id: "templates.EditorialNewsletterEmail",
    version: "1.0.0",
    label: "Newsletter",
    description: "A regular issue: the masthead, the subject as its headline, sections the writer fills in, and an unsubscribe footer",
    guidance: "Friendly and plain: sentence case, no exclamation marks. One to three short sections, each a Heading and a Text.",
    root: "Email",
    fields: {
      ...newsletter.required,
      // What the issue's writer writes: these elements only, in the brand's look, with one or two buttons.
      body: field.slot({
        label: "Body",
        required: true,
        allow: [Column, Heading, Text, Button, Link],
        styles: "none",
        count: { Button: { min: 1, max: 2 } },
        guidance: "One to three short sections, each a Heading and a Text, and one or two buttons.",
      }),
    },
    rules: {
      plugins: { lint: lint({ kind: "marketing" }) },
      require: { lint: ["contrast", "text-size", "link-text", "alt-text", "unsubscribe", "lang"], core: ["layout/overflow"] },
      links: { domains: brand.links.domains, ...(brand.links.params ? { params: brand.links.params } : {}) },
      root: { lang: true, previewText: true },
    },
    example: {
      ...newsletter.example,
      body: (
        <Column>
          <Heading level={2}>Faster exports</Heading>
          <Text>Exports now finish in half the time, with no settings to change.</Text>
          <Heading level={2}>Notes in your own voice</Heading>
          <Text>Release notes now start from what you've written before, so they sound like you.</Text>
          <Button href={href("/changelog")}>Read the changelog</Button>
        </Column>
      ),
    },
    render(v) {
      return (
        <Email
          width={600}
          title={v.subject}
          previewText={v.preview}
          lang={brand.lang ?? "en"}
          {...(brand.dir ? { dir: brand.dir } : {})}
          theme={brand.theme}
          fonts={brand.fonts}
          style={{ backgroundColor: token("colors.surface"), fontSize: token("fontSizes.body"), lineHeight: token("lineHeights.body") }}
        >
          <Section style={{ padding: [token("spacing.lg"), token("spacing.xl")] }}>
            <Image src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }} alt={brand.logo.alt} style={{ width: 150 }} />
          </Section>
          <Section style={{ backgroundColor: token("colors.background"), padding: [token("spacing.xl"), token("spacing.xl"), token("spacing.sm")] }}>
            <Heading field="subject" level={1}>{v.subject}</Heading>
          </Section>
          <Section field="body" style={{ backgroundColor: token("colors.background"), padding: [token("spacing.md"), token("spacing.xl"), token("spacing.xl")] }}>
            {v.body}
          </Section>
          <Section style={{ padding: [token("spacing.lg"), token("spacing.xl")] }}>
            <Text style={{ fontSize: token("fontSizes.small"), color: token("colors.muted") }}>
              {brand.name}
              {brand.address ? `, ${brand.address}` : ""}. <Link href={href("/unsubscribe")}>Unsubscribe from these emails</Link>
            </Text>
          </Section>
        </Email>
      );
    },
  });
}

export default editorialNewsletter(brand);

