  },
} as const;

// From ledger/parts.tsx
/** A link's address: a path on the brand's site, or a full URL, with the brand's required parameters. */
function ledgerHref(brand: Brand, to: string | { href: string }): string {
  const url = new URL(typeof to === "string" ? to : to.href, brand.links.site);
  for (const [key, value] of Object.entries(brand.links.params ?? {})) url.searchParams.set(key, value);
  return url.toString();
}

/** The brand's link rules, for every Ledger template. */
function ledgerLinks(brand: Brand) {
  return { domains: brand.links.domains, ...(brand.links.params ? { params: brand.links.params } : {}) };
}

/** The rules a Ledger email holds to. */
function ledgerEmailRules(brand: Brand) {
  return {
    plugins: { lint: lint() },
    require: { lint: ["contrast", "text-size", "link-text", "alt-text"], core: ["layout/overflow"] },
    links: ledgerLinks(brand),
    root: { lang: true as const, previewText: true as const },
  };
}

/** Money in the brand's language. */
const ledgerMoney = (brand: Brand, currency: string) => new Intl.NumberFormat(brand.lang ?? "en", { style: "currency", currency });

/** A label over a value. */
function LedgerFact({ label, value, field, align }: { label: string; value: string; field?: string; align?: "left" | "right" }) {
  return (
    <Column style={{ gap: 2 }}>
      <Text style={{ fontSize: token("fontSizes.small"), color: token("colors.muted"), ...(align ? { textAlign: align } : {}) }}>{label}</Text>
      <Text {...(field ? { field } : {})} style={{ fontWeight: 700, ...(align ? { textAlign: align } : {}) }}>
        {value}
      </Text>
    </Column>
  );
}

/** The letterhead: the logo, and the brand's address beside it. */
function LedgerLetterhead({ brand }: { brand: Brand }) {
  return (
    <Row stackOnMobile={false} style={{ alignItems: "center", gap: token("spacing.md") }}>
      <Column>
        <Image src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }} alt={brand.logo.alt} style={{ width: 150 }} />
      </Column>
      <Column>
        <Text style={{ fontSize: token("fontSizes.small"), color: token("colors.muted"), textAlign: "right" }}>
          {brand.name}
          {brand.address ? ` · ${brand.address}` : ""}
        </Text>
      </Column>
    </Row>
  );
}

// The template
function ledgerInvoiceEmail(brand: Brand) {
  return template({
    id: "templates.LedgerInvoiceEmail",
    version: "1.0.0",
    label: "Invoice email",
    description: "The email that sends an invoice: the amount due, the due date, the lines, and a button to pay online",
    guidance: "Send it with the invoice PDF attached. The amount is added up from the lines.",
    root: "Email",
    fields: { ...invoice.required },
    rules: ledgerEmailRules(brand),
    example: { ...invoice.example },
    render(v) {
      const money = ledgerMoney(brand, v.currency);
      const total = v.lines.reduce((sum, line) => sum + line.quantity * line.price, 0);
      const due = formatDate(v.due, brand.lang ?? "en", { month: "long", day: "numeric", year: "numeric" });
      return (
        <Email
          width={600}
          title={`Invoice ${v.number} from ${brand.name}`}
          previewText={`${money.format(total)} due ${due}`}
          lang={brand.lang ?? "en"}
          {...(brand.dir ? { dir: brand.dir } : {})}
          theme={brand.theme}
          fonts={brand.fonts}
          style={{ fontSize: token("fontSizes.body"), lineHeight: token("lineHeights.body") }}
        >
          <Column style={{ padding: token("spacing.xl"), gap: token("spacing.lg") }}>
            <LedgerLetterhead brand={brand} />
            <Column style={{ gap: token("spacing.sm") }}>
              <Heading level={1}>Invoice {v.number}</Heading>
              <Text>
                Hello {v.customer.name}, here's your invoice from {brand.name}. The PDF is attached.
              </Text>
            </Column>
            <Column style={{ backgroundColor: token("colors.surface"), padding: token("spacing.lg"), gap: token("spacing.md"), borderRadius: token("radii.sm") }}>
              <Row stackOnMobile={false} style={{ gap: token("spacing.md") }}>
                <LedgerFact label="Amount due" value={money.format(total)} />
                <LedgerFact label="Due" value={due} field="due" align="right" />
              </Row>
              {v.lines.map((line, i) => (
                <Row key={i} stackOnMobile={false} style={{ gap: token("spacing.md") }}>
                  <Column>
                    <Text>
                      {line.description}
                      {line.quantity > 1 ? ` × ${line.quantity}` : ""}
                    </Text>
                  </Column>
                  <Column style={{ width: 120 }}>
                    <Text style={{ textAlign: "right" }}>{money.format(line.quantity * line.price)}</Text>
                  </Column>
                </Row>
              ))}
            </Column>
            <Button field="pay" href={ledgerHref(brand, v.pay)} style={{ borderRadius: token("radii.sm"), padding: [token("spacing.sm"), token("spacing.lg")] }}>
              Pay {money.format(total)} online
            </Button>
            <Text style={{ fontSize: token("fontSizes.small"), color: token("colors.muted") }}>
              Questions about this invoice? <Link href={ledgerHref(brand, "/billing")}>Visit {brand.name} billing</Link>
            </Text>
          </Column>
        </Email>
      );
    },
  });
}

export default ledgerInvoiceEmail(brand);

